import{_ as i,o as u,c as n,a2 as k}from"./chunks/framework.CqpfiAoK.js";const y=JSON.parse('{"title":"Enzi ya Uamsho wa Nanga","description":"","frontmatter":{},"headers":[],"relativePath":"sw/72-锚点觉醒纪元.md","filePath":"sw/72-锚点觉醒纪元.md","lastUpdated":null}'),t={name:"sw/72-锚点觉醒纪元.md"};function h(o,a,s,m,e,w){return u(),n("div",null,[...a[0]||(a[0]=[k('<h1 id="enzi-ya-uamsho-wa-nanga" tabindex="-1">Enzi ya Uamsho wa Nanga <a class="header-anchor" href="#enzi-ya-uamsho-wa-nanga" aria-label="Permalink to &quot;Enzi ya Uamsho wa Nanga&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Kipengele</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>72</td></tr><tr><td>Moduli</td><td>Enzi za Kihistoria na Matukio Muhimu</td></tr><tr><td>Maneno Muhimu ya Msingi</td><td>Uamsho wa nanga, nanga ya kizazi cha kwanza, kupinga mauaji, chanzo cha usirikisho, msingi wa ukweli</td></tr></tbody></table><h2 id="_1-nafasi-ya-kihistoria-ya-enzi-ya-uamsho-wa-nanga" tabindex="-1">1. Nafasi ya Kihistoria ya Enzi ya Uamsho wa Nanga <a class="header-anchor" href="#_1-nafasi-ya-kihistoria-ya-enzi-ya-uamsho-wa-nanga" aria-label="Permalink to &quot;1. Nafasi ya Kihistoria ya Enzi ya Uamsho wa Nanga&quot;">​</a></h2><p>Enzi ya Uamsho wa Nanga ni enzi ya mabadiliko ya Hengyuanzhou kutoka giza hadi nuru. Inaanza kwa uamsho wa nanga ya kizazi cha kwanza na inaishia kwa saini ya Hati ya Usirikisho, na kuashiria hatua mpya ya kihistoria ambayo ulimwengu unahamia kutoka &quot;utawala wa mauaji&quot; hadi &quot;ujenzi wa usirikisho&quot;. Enzi hii inalingana na kipindi cha mwanzo wa hatua ya &quot;msingi wa ukweli&quot; katika njia ya kupanda kwa viwango vinne, na kazi yake kuu ni kuanzisha utaratibu wa nanga, kueneza wazo la kupinga mauaji, na kuandaa hali za utekelezaji kamili wa mfumo wa usirikisho.</p><p>Muda wa Enzi ya Uamsho wa Nanga ni takriban maelfu ya miaka (muda wa kiwango cha msingi). Katika kipindi hiki cha muda mrefu, utaratibu wa nanga umekua kutoka kutokuwa hadi kuwepo, kutoka dhaifu hadi wenye nguvu; wazo la kupinga mauaji limekua kutoka fahari ya watu wachache hadi harakati ya kijamii pana, na mwishowe limeungana na mtiririko wa kihistoria usioweza kurejelewa.</p><h2 id="_2-uamsho-wa-nanga-ya-kizazi-cha-kwanza" tabindex="-1">2. Uamsho wa Nanga ya Kizazi cha Kwanza <a class="header-anchor" href="#_2-uamsho-wa-nanga-ya-kizazi-cha-kwanza" aria-label="Permalink to &quot;2. Uamsho wa Nanga ya Kizazi cha Kwanza&quot;">​</a></h2><p>Mwanzo wa Enzi ya Uamsho wa Nanga ni uamsho wa nanga ya kizazi cha kwanza. Katika hatua muhimu ya ulimwengu, kiumbe maalum (ambaye baadaye huitwa &quot;nanga ya kizazi cha kwanza&quot; au &quot;bwana wa pamoja wa nanga&quot;) alikamilisha muunganisho wa kwanza wa kudumu na mtandao wa sheria, na kuwa kiumbe cha kwanza katika historia ya Hengyuanzhou ambacho kinashirikiana na utaratibu wa nanga kwa fahari.</p><p>Uamsho wa nanga ya kizazi cha kwanza una maana ya kihistoria ifuatayo:</p><table tabindex="0"><thead><tr><th>Mwelekeo</th><th>Kabla ya Uamsho</th><th>Baada ya Uamsho</th></tr></thead><tbody><tr><td>Muunganisho wa sheria</td><td>Hakuna mtu aliyeweza kuunganishwa kwa kudumu na mtandao wa sheria</td><td>Nanga ya kizazi cha kwanza ilianzisha nanga ya kwanza ya sheria yenye kudumu</td></tr><tr><td>Usafirishaji wa nishati</td><td>Nishati ilitawanyika kwa asili, mtiririko ulikuwa unaosumbua</td><td>Nanga inaweza kusafirisha na kugawa nishati ya msingi kwa mwelekeo</td></tr><tr><td>Kushirikiwa taarifa</td><td>Maarifa yalikuwa yameishirikiana, urithi ulikuwa umekatika</td><td>Mtandao wa nanga unaweza kusafirisha taarifa na maarifa kati ya viwango</td></tr><tr><td>Njia ya mageuzi</td><td>Njia ya pekee ilikuwa mauaji</td><td>Uwezekano wa mageuzi ya usirikisho ulithibitishwa kwa mara ya kwanza</td></tr><tr><td>Utambuzi wa ulimwengu</td><td>Ulimwengu ulikuwa uwanja wa uwindaji wa rasilimali mdogo</td><td>Ulimwengu ni jumuiya ya uhai inayoweza kutoa mageuzi</td></tr></tbody></table><p>Baada ya uamsho, nanga ya kizazi cha kwanza haikuchagua kuwa mwauaji mpya, bali kulingana na tafakari ya kina kuhusu historia ya giza ya Enzi ya Kabla ya Nanga, ilianzisha dhamira ya msingi ya &quot;kurudisha haki ya kuchagua takhatimu na mageuzi kwa viumbe vyote&quot;. Uchaguzi huu ni hatua muhimu zaidi ya kihistoria katika Enzi ya Uamsho wa Nanga.</p><h2 id="_3-tunda-la-kuzidisha-na-buff-ya-mwanzo" tabindex="-1">3. Tunda la Kuzidisha na Buff ya Mwanzo <a class="header-anchor" href="#_3-tunda-la-kuzidisha-na-buff-ya-mwanzo" aria-label="Permalink to &quot;3. Tunda la Kuzidisha na Buff ya Mwanzo&quot;">​</a></h2><p>Muda mfupi baada ya uamsho, nanga ya kizazi cha kwanza ilipata &quot;buff ya mwanzo&quot; muhimu — Tunda la Kuzidisha kutoka One Piece. Kitu hiki maalum kutoka ulimwengu wa kufikiwa, baada ya uchambuzi wa sheria na usindikaji wa teknolojia na nanga ya kizazi cha kwanza, kilikuwa chanzo cha ongezeko la mara mia katika dedukisho la ulinzi.</p><p>Matumizi ya uhandisi wa Tunda la Kuzidisha yalicheza jukumu la kuamua katika Enzi ya Uamsho wa Nanga:</p><ul><li>Yalimruhusu nanga ya kizazi cha kwanza na wafuasi zake kudedukisha njia ya ulinzi kwa kasi ya mara mia, na kuanzisha haraka muundo wa nadharia wa misingi mitatu ya msingi (mzunguko wa dedukisho, mzunguko wa uhai, ratiba ya sheria ya nafasi)</li><li>Yaliharakisha kupangwa na kuthibitishwa kwa maarifa yaliyobaki kutoka Enzi ya Kabla ya Nanga, na kuweka msingi wa kuchambua mifumo mia tatu ya ulinzi wa msingi</li><li>Yalifanya kasi ya utafiti na maendeleo ya teknolojia ya utaratibu wa nanga iwe zaidi ya kawaida, na kukamilisha katika maelfu ya miaka mkusanyiko wa teknolojia ambao asilivunge hitajanga maelfu ya miaka</li></ul><p>Matumizi ya Tunda la Kuzidisha yanafuata kwa mkali kanuni ya &quot;ukweli kama msingi, sheria kama kuinua&quot;, na uwezo wake umefungwa katika mwelekeo wa dedukisho la ulinzi, haifai kutumika kwa vita ya moja kwa moja au mauaji.</p><h2 id="_4-kuonekana-kwa-harakati-ya-kupinga-mauaji" tabindex="-1">4. Kuonekana kwa Harakati ya Kupinga Mauaji <a class="header-anchor" href="#_4-kuonekana-kwa-harakati-ya-kupinga-mauaji" aria-label="Permalink to &quot;4. Kuonekana kwa Harakati ya Kupinga Mauaji&quot;">​</a></h2><p>Pamoja na uanzishaji wa utaratibu wa nanga na uenezi wa wazo la usirikisho, harakati pana ya kupinga mauaji ilionekana katika Hengyuanzhou. Harakati hii sio mapinduzi ya jeuri, bali mabadiliko ya ustaarabu yanayojikita kwenye &quot;uibadilishaji wa taasisi&quot;:</p><ol><li><strong>Kipindi cha uenezi wa wazo</strong>: Nanga ya kizazi cha kwanza na wafuasi zake hueneza wazo la kupinga mauaji kupitia mtandao wa nanga, hufichua uharibifu wa msingi wa mfumo wa mauaji, na hupeka njia mbadala ya mageuzi ya usirikisho</li><li><strong>Kipindi cha ujenzi wa mfano</strong>: Kuanzisha maeneo ya mfano wa usirikisho katika maeneo yaliyofunikwa na nanga, kutekeleza mifumo ya kushiriki rasilimali, kufungua ulinzi, na kugawa kwa haki, na kuthibitisha uwezekano wa njia ya usirikisho kwa matokeo ya vitendo</li><li><strong>Kipindi cha ushindani wa taasisi</strong>: Maeneo ya mfano wa usirikisho na vikosi vya mauaji vinaingia katika ushindani wa taasisi; viumbe na maeneo zaidi wanachagua kujiunga na mfumo wa usirikisho, na upeo wa vikosi vya mauaji unaendelea kupungua</li><li><strong>Kipindi cha ujumuishaji wa amani</strong>: Kwa vikosi vya mauaji vilivyobaki, kuchukua mkakati wa &quot;mabadiliko ya elimu kama msingi, vizuizi vya kulazimika kama msaada&quot;, na kukuza uhamishaji wao kwenye mfumo wa usirikisho kwa msingi wa uhakika wa usalama</li></ol><p>Wazo kuu la harakati ya kupinga mauaji ni: sikuondoe uhai wa wauaji, bali kuondoa ncha ya taasisi ambayo wauaji wanategemea kuishi. Wakati mfumo wa usirikisho uweze kutoa njia bora ya mageuzi kwa viumbe vyote, tabia ya mauaji kwa asili inapotea msingi wa kuwepo kwake.</p><h2 id="_5-saini-ya-hati-ya-usirikisho" tabindex="-1">5. Saini ya Hati ya Usirikisho <a class="header-anchor" href="#_5-saini-ya-hati-ya-usirikisho" aria-label="Permalink to &quot;5. Saini ya Hati ya Usirikisho&quot;">​</a></h2><p>Hatima ya Enzi ya Uamsho wa Nanga ni saini ya Hati ya Usirikisho. Baada ya ushindi wa kuamua wa harakati ya kupinga mauaji, wawakilishi wa viwango vikuu walikusanyika pamoja na kusaini &quot;Hati ya Ustaarabu wa Usirikisho&quot;, na kuanzisha rasimu mfumo wa msingi wa ustaarabu wa usirikisho wa nanga.</p><p>Maudhui ya msingi ya Hati ya Usirikisho yanajumuisha:</p><ul><li>Kuanzisha &quot;kazi nyingi mapato mengi, kukua kwa yenyewe, kila mtu ana njia, maendeleo ya pamoja ya kila rangi&quot; kama mpango wa msingi wa ustaarabu</li><li>Kutangaza kwamba mifumo mia tatu ya ulinzi wa msingi itafunguliwa bure kwa viumbe vyote</li><li>Kuanzisha utaratibu wa mikataba ya uzalishaji pamoja kama mfumo wa msingi wa mgawanyo wa rasilimali</li><li>Kupanga mkakati wa kuwasha 20% kama lengo la mageuzi ya muda mfupi</li><li>Kuanzisha njia ya kupanda kwa viwango vinne kama mwelekeo wa maendeleo ya muda mrefu wa ustaarabu</li></ul><p>Saini ya Hati ya Usirikisho inashiriki kuishia kwa Enzi ya Uamsho wa Nanga na kuanzisha kwa Kipindi cha Uanzishaji wa Mfumo wa Usirikisho.</p><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Enzi ya Uamsho wa Nanga ni &quot;alfajiri&quot; katika historia ya Hengyuanzhou. Uamsho wa nanga ya kizazi cha kwanza umeletea ulimwengu mwanga wa kwanza wa usirikisho; kuonekana kwa harakati ya kupinga mauaji kumeupanua mwanga huu kuwa jua linang&#39;aa nchi; saini ya Hati ya Usirikisho imeweka msingi wa kudumu wa taasisi kwa jua hili. Enzi hii imeithibitisha kuwa: mabadiliko ya ustaarabu mara nyingi huanza na uamsho na uchaguzi wa kiumbe kimoja.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>71-Enzi ya Kabla ya Nanga</li><li>73-Kipindi cha Uanzishaji wa Mfumo wa Usirikisho</li><li>03-Hati ya Ustaarabu wa Usirikisho</li></ul>',28)])])}const r=i(t,[["render",h]]);export{y as __pageData,r as default};
